def choose_move(observation):
    x, y = observation['self_position']
    targets = observation.get('resources', [])
    obstacles = set(observation.get('obstacles', []))
    width, height = observation['grid_width'], observation['grid_height']
    def dist(p): return abs(p[0]-x)+abs(p[1]-y)
    closest = None
    min_d = float('inf')
    for t in targets:
        d = dist(t)
        if d < min_d:
            min_d = d
            closest = t
    if closest:
        dx = closest[0]-x
        dy = closest[1]-y
        move_x = (dx > 0) - (dx < 0)
        move_y = (dy > 0) - (dy < 0)
        for mx, my in [(move_x,0), (0,move_y)]:
            nx, ny = x+mx, y+my
            if 0 <= nx < width and 0 <= ny < height and (nx, ny) not in obstacles:
                return [mx, my]
    for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
        nx, ny = x+dx,y+dy
        if 0 <= nx < width and 0 <= ny < height and (nx, ny) not in obstacles:
            return [dx, dy]
    return [0,0]
